'use strict';
window.CRATE_EVENTS = [{"year": 1973, "date": "1973-08-11", "category": "BLOCK PARTY", "title": "ブロンクスのBack to School Jam", "text": "Kool HercとCindy Campbellによる1520 Sedgwick Avenueのパーティー。Hip Hopの起点として語り継がれる一夜。", "source": "Smithsonian", "url": "https://www.smithsonianmag.com/smithsonian-institution/how-the-block-party-became-an-urban-phenomenon-180980560/"}, {"year": 1979, "date": "1979", "category": "RECORDS", "title": "Rapper’s Delightがレコードになる", "text": "Sugarhill Gangの一曲が、パーティーの外へ届く。1979年の盤はスミソニアンにも収蔵されている。", "source": "Smithsonian", "url": "https://americanhistory.si.edu/collections/object/nmah_1320076"}, {"year": 1982, "date": "1982", "category": "STREET VOICES", "title": "The Messageが街の現実を伝える", "text": "Grandmaster Flash & the Furious Fiveの作品。踊るための音楽に、暮らしの厳しさを語る声が重なる。", "source": "Smithsonian", "url": "https://collections.si.edu/search/record/ark%3A/65665/fd5f2ba7e6cb0434305961bed18556b4b2a"}, {"year": 1983, "date": "1983", "category": "GRAFFITI / FILM", "title": "Style WarsがPBSで放送される", "text": "Tony SilverとHenry Chalfantの映画が、ニューヨークのグラフィティとHip Hopの現場を記録。壁も列車も、文化の大切なページになる。", "source": "Style Wars公式", "url": "https://www.stylewars.com/about"}, {"year": 1986, "date": "1986", "category": "CROSSOVER", "title": "RUN DMCとAerosmithのWalk This Way", "text": "ラップとロックが同じ曲で出会う。ジャンルを横断する共演が、映像とともに広いリスナーへ届く。", "source": "Rock Hall", "url": "https://rockhall.com/inductees/run-dmc/"}, {"year": 1989, "date": "1989", "category": "GRAMMY", "title": "ラップ部門で初のGRAMMY受賞", "text": "DJ Jazzy Jeff & the Fresh PrinceのParents Just Don’t UnderstandがBest Rap Performanceを受賞。賞の舞台にもラップの名前が刻まれる。", "source": "Recording Academy", "url": "https://www.grammy.com/awards/31st-annual-grammy-awards/"}, {"year": 1996, "date": "1996-09-13", "category": "IN MEMORIAM", "title": "Tupac Shakurが亡くなる", "text": "Tupac Shakurが25歳で死去。対立の見出しだけでなく、残された歌と声から、この時代を聴き直したい。", "source": "Rock Hall所蔵資料", "url": "https://catalog.rockhall.com/rrhof-ais/Details/archive/110130110"}, {"year": 1997, "date": "1997-03-09", "category": "IN MEMORIAM", "title": "The Notorious B.I.G.が亡くなる", "text": "Christopher Wallaceが24歳で死去。東西という二つの言葉では収まらない喪失を、音楽の歴史の中にも残す。", "source": "Rock Hall所蔵資料", "url": "https://catalog.rockhall.com/rrhof-ais/Details/archive/110101584"}, {"year": 1999, "date": "1999", "category": "GRAMMY", "title": "Lauryn Hillが一晩で5部門を受賞", "text": "The Miseducation of Lauryn HillがAlbum of the Yearに。ラップと歌を行き来する作品が、GRAMMYの大きな舞台へ進む。", "source": "Recording Academy", "url": "https://www.grammy.com/news/lauryn-hill-album-year-win-miseducation-grammy-rewind-video-speech/"}, {"year": 2007, "date": "2007", "category": "ROCK HALL", "title": "初のラップ・グループの殿堂入り", "text": "Grandmaster Flash & the Furious FiveがRock & Roll Hall of Fameへ。ターンテーブルの仕事も音楽史へ刻まれていく。", "source": "Rock Hall", "url": "https://rockhall.com/inductees/grandmaster-flash-and-furious-five/"}, {"year": 2023, "date": "2023", "category": "HIP HOP 50", "title": "Hip Hopの50年を祝う", "text": "GRAMMYの記念番組にDJ Jazzy Jeff & the Fresh Prince、Queen Latifah、Commonらが登場。世代を越えて、文化の半世紀を祝う。", "source": "Recording Academy", "url": "https://www.grammy.com/news/a-grammy-salute-to-50-years-of-hip-hop-recap-photos/"}];
// Both views are derived from the same editorial records and representative samples.
window.CrateChronology=(songs,esc,options={})=>{
 const events=options.events||[];
 if(!songs.length&&!events.length)return '<p class="empty">この条件の曲はまだありません。条件を変えて掘ってみてください。</p>';
 const years=[...new Set([...songs.map(s=>s.year),...events.map(e=>e.year)])].sort((a,b)=>a-b);
 const record=s=>{const q=s.samples.find(x=>x.main),source=q?'<div class="tc-source"><span class="tc-source-label">MAIN SAMPLE'+(q.year?' · '+q.year:'')+'</span><strong>'+esc(q.title)+'</strong><span>'+esc(q.artist)+'</span></div>':'';return '<article class="tc-record"><div class="tc-record-head"><span class="tc-city">'+esc(s.region)+'</span>'+(s.yearBasis?'<span class="tc-date-note">'+(s.yearBasis.includes('配信版')?'配信版の年 · 初出年は照合中':'発表年の根拠は解説を参照')+'</span>':'')+'<a href="#/song/'+s.id+'" aria-label="'+esc(s.title+' / '+s.artist+'の解説を読む')+'"><h3>'+esc(s.title)+'</h3><p>'+esc(s.artist)+'</p><span class="tc-arrow" aria-hidden="true">↗</span></a></div>'+source+'</article>'};
 const news=e=>'<article class="tc-event"><div class="tc-event-meta"><time datetime="'+esc(e.date)+'">'+esc(e.date.replaceAll('-','.'))+'</time><span>'+esc(e.category)+'</span></div><h3>'+esc(e.title)+'</h3><p>'+esc(e.text)+'</p><a href="'+esc(e.url)+'" target="_blank" rel="noopener">出典 '+esc(e.source)+' ↗</a></article>';
 return '<nav class="tc-years" aria-label="年へ移動">'+years.map(y=>'<a href="#timeline-year-'+y+'" data-timeline-year="'+y+'">'+y+'</a>').join('')+'</nav><p class="tc-history-key">RECORDS 楽曲 · CULTURE 時代の出来事</p><div class="tc-history">'+years.map(y=>{const list=songs.filter(s=>s.year===y),items=events.filter(e=>e.year===y),regions=[...new Set(list.flatMap(s=>s.region.split(' / ')))];return '<section class="tc-year-group" id="timeline-year-'+y+'" tabindex="-1"><header class="tc-year-heading"><h2>'+y+'</h2><span>'+(list.length?list.length+' RECORDS':'CULTURE')+'</span><p>'+esc(regions.join(' · '))+'</p></header><div class="tc-year-records">'+list.slice(0,4).map(record).join('')+(list.length>4?'<details class="tc-more"><summary>'+y+'年の残り'+(list.length-4)+'曲も見る</summary>'+list.slice(4).map(record).join('')+'</details>':'')+items.map(news).join('')+'</div></section>'}).join('')+'</div>';
};
window.CrateTimeline=(songs,esc,options={})=>{
 if(!songs.length)return '<p class="empty">この条件の曲はまだありません。条件を変えて掘ってみてください。</p>';
 const years=songs.flatMap(s=>[s.year,...s.samples.filter(q=>q.main&&q.year).map(q=>q.year)]),start=Math.floor(Math.min(...years)/5)*5,end=Math.ceil(Math.max(...years)/5)*5,px=options.px||28,width=Math.max(500,(end-start)*px+170),xx=y=>24+(y-start)*px;
 let axis='',grid='';for(let y=start;y<=end;y++){if(y%5===0)axis+='<span style="left:'+xx(y)+'px">'+y+'</span>';grid+='<i style="left:'+xx(y)+'px" class="'+(y%5===0?'major':'')+'"></i>'}
 const rows=songs.map(s=>{const q=s.samples.find(q=>q.main&&q.year),x=xx(s.year),sx=q?xx(q.year):0;return '<div class="tm-row"><a class="tm-label" href="#/song/'+s.id+'"><strong>'+esc(s.title)+'</strong><span>'+esc(s.artist)+'</span><small>'+s.year+' · '+esc(s.region)+(s.yearBasis?' · 年を照合中':'')+'</small></a><div class="tm-plot">'+grid+(q?'<span class="tm-link" style="left:'+Math.min(sx,x)+'px;width:'+Math.abs(x-sx)+'px"></span><span class="tm-source-dot" style="left:'+sx+'px"></span><span class="tm-source-text" style="left:'+Math.min(sx,width-215)+'px"><b>'+q.year+'</b> '+esc(q.title)+'<small>'+esc(q.artist)+'</small></span>':'')+'<a class="tm-song-dot" style="left:'+x+'px" href="#/song/'+s.id+'" aria-label="'+esc(s.title+' / '+s.year)+'"><span>'+s.year+'</span></a></div></div>'});
 return '<p class="tm-help">灰色の点から青い点へ。元になった音が、いつ新しい曲になったか。<br>左右に動かしても曲名は固定、上下に動かしても年代軸は固定です。</p><div class="tm-scroll" tabindex="0" role="region" aria-label="楽曲とメインサンプルの年代比較。上下左右にスクロールできます"><div class="tm-canvas" style="--tm-width:'+width+'px"><div class="tm-axis"><div class="tm-corner">RECORD / CITY</div><div class="tm-scale">'+axis+'</div></div>'+rows.join('')+'</div></div><div class="tl-legend"><span><i></i>楽曲の発表年</span><span><i class="sample-dot"></i>メインサンプルの発表年</span></div>';
};
